-- ============================================================================
-- UCO Bank Realty Portal - Core Schema DDL
-- Database: Oracle Database 19c / 21c / 23c Enterprise Edition / XE
-- Execution Environment: SQL*Plus / Oracle SQL Developer / Toad
-- Target Environments: UAT, PRE-PROD, PRODUCTION
-- Notes:
--   - Uses Oracle Identity columns (GENERATED BY DEFAULT AS IDENTITY)
--   - In-database Oracle SecureFiles BLOB for project photos
--   - Six tables: projects (approved only), project_staging (maker working copy), project_images, leads, audit_log, login_audit
--   - The only script a NEW database (UAT / production) needs. Run once as the application schema user.
-- ============================================================================

-- 1. PROJECTS TABLE (MASTER): holds only APPROVED records (status APPROVED, or DELETED which is kept for the logs).
--    Everything a maker is still working on lives in PROJECT_STAGING until a checker approves it.
CREATE TABLE projects (
  id VARCHAR2(20) PRIMARY KEY,
  sr_no NUMBER,
  zone_name VARCHAR2(100),
  branch_name VARCHAR2(100),
  state_name VARCHAR2(100),
  city_name VARCHAR2(100),
  project_name VARCHAR2(255) NOT NULL,
  rera_no VARCHAR2(100),
  property_id VARCHAR2(100),
  type_of_unit VARCHAR2(100),
  approval_date DATE,
  total_inventory NUMBER,
  unsold_inventory NUMBER,
  inventory_as_on_date DATE,
  amenities CLOB,
  start_date DATE,
  completion_date DATE,
  apt_per_floor NUMBER,
  no_of_towers NUMBER,
  total_project_area VARCHAR2(100),
  carpet_min VARCHAR2(50),
  carpet_max VARCHAR2(50),
  buildup_min VARCHAR2(50),
  buildup_max VARCHAR2(50),
  dist_railway VARCHAR2(100),
  dist_airport VARCHAR2(100),
  avg_rate VARCHAR2(100),
  budget_min VARCHAR2(100),
  budget_max VARCHAR2(100),
  builder_name VARCHAR2(255),
  project_address VARCHAR2(500),
  pin_code VARCHAR2(10),
  promoter1 VARCHAR2(255),
  promoter2 VARCHAR2(255),
  promoter3 VARCHAR2(255),
  promoter4 VARCHAR2(255),
  promoter5 VARCHAR2(255),
  sales_exec_name VARCHAR2(255),
  sales_mobile VARCHAR2(15),
  sales_email VARCHAR2(255),
  website VARCHAR2(255),
  builder_rating VARCHAR2(50),
  builder_bg CLOB,
  branch_head_name VARCHAR2(255),
  branch_head_number VARCHAR2(15),
  rel_exec_name VARCHAR2(255),
  rel_exec_number VARCHAR2(15),
  valid_upto DATE,
  renewal_pending VARCHAR2(20),
  approval_sought VARCHAR2(100),
  certificate_path VARCHAR2(500),
  floor_plan_path VARCHAR2(500),
  total_img_count NUMBER DEFAULT 0,
  verified_img_count NUMBER DEFAULT 0,
  status VARCHAR2(30) DEFAULT 'APPROVED' NOT NULL,   -- a master row is an APPROVED record, or DELETED (kept for the logs)
  is_active NUMBER(1) DEFAULT 1 NOT NULL,
  is_published NUMBER(1) DEFAULT 1 NOT NULL,
  created_by VARCHAR2(50),                           -- the maker who raised the project
  checked_by VARCHAR2(50),                           -- the checker who last approved it
  checker_comment VARCHAR2(1000),
  deleted_at TIMESTAMP,                              -- set when a checker approves a deletion
  deleted_by VARCHAR2(50),
  row_version NUMBER DEFAULT 0 NOT NULL,             -- optimistic locking
  created_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT chk_inventory CHECK (unsold_inventory IS NULL OR total_inventory IS NULL OR unsold_inventory <= total_inventory)
);

-- 2. PROJECT_STAGING: the maker's working table (maker-checker staging).
--     One row per request: CREATE (a new project), UPDATE (edit / unit reduction of an approved project) or
--     DELETE (deletion of an approved project). The maker edits THIS row until he sends it for approval; only when
--     a checker approves is it applied to PROJECTS (insert / update / mark DELETED). Approved, rejected and
--     withdrawn rows stay here as the history of who asked for what.
CREATE TABLE project_staging (
  id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  project_id VARCHAR2(20) NOT NULL,           -- the project code: allocated at CREATE, becomes projects.id on approval
  request_type VARCHAR2(10) NOT NULL,         -- CREATE | UPDATE | DELETE
  status VARCHAR2(20) NOT NULL,               -- DRAFT | PENDING_APPROVAL | NEEDS_CORRECTION | APPROVED | REJECTED | WITHDRAWN
  zone_name VARCHAR2(100),
  branch_name VARCHAR2(100),
  state_name VARCHAR2(100),
  city_name VARCHAR2(100),
  project_name VARCHAR2(255),
  rera_no VARCHAR2(100),
  property_id VARCHAR2(100),
  type_of_unit VARCHAR2(100),
  approval_date DATE,
  total_inventory NUMBER,
  unsold_inventory NUMBER,
  inventory_as_on_date DATE,
  amenities CLOB,
  start_date DATE,
  completion_date DATE,
  apt_per_floor NUMBER,
  no_of_towers NUMBER,
  total_project_area VARCHAR2(100),
  carpet_min VARCHAR2(50),
  carpet_max VARCHAR2(50),
  buildup_min VARCHAR2(50),
  buildup_max VARCHAR2(50),
  dist_railway VARCHAR2(100),
  dist_airport VARCHAR2(100),
  avg_rate VARCHAR2(100),
  budget_min VARCHAR2(100),
  budget_max VARCHAR2(100),
  builder_name VARCHAR2(255),
  project_address VARCHAR2(500),
  pin_code VARCHAR2(10),
  promoter1 VARCHAR2(255),
  promoter2 VARCHAR2(255),
  promoter3 VARCHAR2(255),
  promoter4 VARCHAR2(255),
  promoter5 VARCHAR2(255),
  sales_exec_name VARCHAR2(255),
  sales_mobile VARCHAR2(15),
  sales_email VARCHAR2(255),
  website VARCHAR2(255),
  builder_rating VARCHAR2(50),
  builder_bg CLOB,
  branch_head_name VARCHAR2(255),
  branch_head_number VARCHAR2(15),
  rel_exec_name VARCHAR2(255),
  rel_exec_number VARCHAR2(15),
  valid_upto DATE,
  renewal_pending VARCHAR2(20),
  approval_sought VARCHAR2(100),
  remove_image_ids VARCHAR2(500),             -- UPDATE: live photos to remove when approved
  reason VARCHAR2(1000 CHAR),                 -- DELETE / unit reduction: the maker's reason
  summary VARCHAR2(1000 CHAR),                -- what changes (filled when sent for approval)
  base_version NUMBER,                        -- UPDATE / DELETE: projects.row_version when the draft was opened
  row_version NUMBER DEFAULT 0 NOT NULL,      -- optimistic locking (two checkers cannot both decide it)
  created_by VARCHAR2(50) NOT NULL,           -- the maker
  checked_by VARCHAR2(50),
  checker_comment VARCHAR2(1000 CHAR),
  created_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
  updated_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
  submitted_at TIMESTAMP,
  decided_at TIMESTAMP,
  CONSTRAINT chk_staging_inventory CHECK (unsold_inventory IS NULL OR total_inventory IS NULL OR unsold_inventory <= total_inventory)
);
CREATE INDEX idx_staging_project ON project_staging(project_id, status);
CREATE INDEX idx_staging_status ON project_staging(status, request_type);
-- at most ONE open request per project (the database enforces it, not only the application)
CREATE UNIQUE INDEX ux_staging_one_open ON project_staging (
  CASE WHEN status IN ('DRAFT','PENDING_APPROVAL','NEEDS_CORRECTION') THEN project_id END);

-- 3. PROJECT IMAGES TABLE (SecureFiles BLOB Storage)
CREATE TABLE project_images (
  id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  project_id VARCHAR2(20),                    -- set for a live (approved) photo
  staging_id NUMBER,                          -- set while the photo belongs to a maker's unapproved work (never shown to customers)
  file_name VARCHAR2(255),
  mime_type VARCHAR2(100),
  file_size NUMBER(19,0),
  file_data BLOB,
  file_path VARCHAR2(500) NOT NULL,
  is_verified NUMBER(1) DEFAULT 0 NOT NULL,
  uploaded_by VARCHAR2(50),
  uploaded_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT fk_project_images_project FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE,
  CONSTRAINT fk_project_images_staging FOREIGN KEY (staging_id) REFERENCES project_staging(id) ON DELETE CASCADE,
  CONSTRAINT chk_image_owner CHECK ((project_id IS NULL AND staging_id IS NOT NULL) OR (project_id IS NOT NULL AND staging_id IS NULL))
)
LOB (file_data) STORE AS SECUREFILE (
  ENABLE STORAGE IN ROW
  CHUNK 8192
  RETENTION AUTO
  CACHE
);

-- 4. LEADS TABLE
CREATE TABLE leads (
  id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  customer_name VARCHAR2(255) NOT NULL,
  phone VARCHAR2(15) NOT NULL,
  project_id VARCHAR2(20),
  state_name VARCHAR2(100),
  city_name VARCHAR2(100),
  branch_selected VARCHAR2(100),
  status VARCHAR2(30),
  otp_verified NUMBER(1) NULL,
  created_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT fk_leads_project FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE SET NULL
);

-- 5. AUDIT LOG TABLE
CREATE TABLE audit_log (
  id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  entity_type VARCHAR2(50) NOT NULL,
  entity_id VARCHAR2(100) NOT NULL,
  action VARCHAR2(50) NOT NULL,
  by_user VARCHAR2(50),
  old_val VARCHAR2(1000 CHAR),
  new_val VARCHAR2(1000 CHAR),
  created_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL
);

-- 6. LOGIN AUDIT TABLE (Security and authentication attempts)
CREATE TABLE login_audit (
  id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  username VARCHAR2(100),
  ip_address VARCHAR2(50),
  success NUMBER(1) NOT NULL,
  remarks VARCHAR2(500 CHAR),
  login_time TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL
);

-- ============================================================================
-- PERFORMANCE INDEXES
-- ============================================================================
CREATE INDEX idx_proj_status_pub ON projects(status, is_active, is_published);
CREATE INDEX idx_proj_zone ON projects(zone_name);
CREATE INDEX idx_proj_branch ON projects(branch_name);
CREATE INDEX idx_proj_geo ON projects(state_name, city_name);
CREATE INDEX idx_proj_img_pid ON project_images(project_id);
CREATE INDEX idx_img_staging ON project_images(staging_id);
CREATE INDEX idx_leads_date ON leads(created_at);
CREATE INDEX idx_leads_status ON leads(status);
CREATE INDEX idx_audit_entity ON audit_log(entity_type, entity_id);
CREATE INDEX idx_audit_created ON audit_log(created_at DESC);
CREATE INDEX idx_login_audit_time ON login_audit(login_time DESC);
CREATE INDEX idx_login_audit_user ON login_audit(username);

PROMPT Tables and indexes created successfully.
